(()=>{const examples={new:{kind:'NEW DEPENDENCY',title:'A new connection appears.',copy:'A network flow reveals Checkout → Payments. The projection adds the relationship.',icon:'+',label:'NEW RELATIONSHIP'},failure:{kind:'FAILING DEPENDENCY',title:'A relationship reports failures.',copy:'Requests from Checkout to Payments fail. The projection can attach a status to that relationship.',icon:'!',label:'DEPENDENCY DEGRADED'},unstable:{kind:'INSTABILITY',title:'The signal changes repeatedly.',copy:'The connection alternates between healthy and degraded. The projection can mark it unstable.',icon:'≈',label:'REPEATED CHANGES'},pattern:{kind:'BEHAVIOR PATTERN',title:'A sequence repeats.',copy:'A recurring sequence in incoming data can be detected by a pattern rule in the projection.',icon:'↻',label:'RECURRING SEQUENCE'}};const visual=document.querySelector('.detect-visual');document.querySelectorAll('[data-detection]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.detection,x=examples[key];document.querySelectorAll('[data-detection]').forEach(e=>{e.classList.toggle('active',e===b);e.setAttribute('aria-pressed',String(e===b))});visual.className='detect-visual '+key;document.getElementById('detect-kind').textContent='EXAMPLE / '+x.kind;document.getElementById('detect-title').textContent=x.title;document.getElementById('detect-copy').textContent=x.copy;document.getElementById('detect-icon').textContent=x.icon;document.getElementById('detect-link-label').textContent=x.label}));})();
